mapper.select:
SELECT M.CHAT_ID, M.NUM, M.TYPE, M.CONTENT, M.ROLE, M.AUTHOR,
       ,
       ,
       UNIX_TIMESTAMP(M.CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT_MESSAGE M
WHERE M.CHAT_ID = #{id}

    AND M.NUM >= #{minNum}


    AND M.NUM <= #{maxNum}



    AND M.CREATED_AT >= FROM_UNIXTIME(#{minTimestamp} / 1000)


    AND M.CREATED_AT <= FROM_UNIXTIME(#{maxTimestamp} / 1000)


ORDER BY M.NUM

    LIMIT #{maxAmount}

SELECT * FROM (
    SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, AUTHOR, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
    FROM T_CHAT_MESSAGE
    WHERE CHAT_ID = #{id}
    ORDER BY NUM DESC
    LIMIT #{maxAmount}
) RECENT
ORDER BY NUM
